from torch import nn
import torch.nn.functional as F
class RB(nn.Module):
 def init(self,i,o):
 super().init();self.c1=nn.Conv2d(i,o,3,1,1);self.c2=nn.Conv2d(o,o,3,1,1);self.n1=nn.GroupNorm(8,o);self.n2=nn.GroupNorm(8,o);self.s=nn.Conv2d(i,o,1) if i!=o else nn.Identity()
 def forward(self,x):return F.silu(self.s(x)+self.n2(self.c2(F.silu(self.n1(self.c1(x))))))
class AG(nn.Module):
 def init(self,c):
 super().init();self.q=nn.Conv2d(c,c//2,1);self.k=nn.Conv2d(c,c//2,1);self.v=nn.Conv2d(c//2,1,1)
 def forward(self,s,g):return s*torch.sigmoid(self.v(F.silu(self.q(s)+self.k(g))))
class RADUNet(nn.Module):
 def init(self):
 super().init();self.p=nn.MaxPool2d(2);self.e1=RB(1,32);self.e2=RB(32,64);self.e3=RB(64,128);self.bot=RB(128,256);self.u3=nn.ConvTranspose2d(256,128,2,2);self.u2=nn.ConvTranspose2d(128,64,2,2);self.u1=nn.ConvTranspose2d(64,32,2,2);self.a3=AG(128);self.a2=AG(64);self.a1=AG(32);self.d3=RB(256,128);self.d2=RB(128,64);self.d1=RB(64,32);self.h=nn.Conv2d(32,3,1)
 def forward(self,x):
