 def init(s,cin=1):
 super().init();s.e1=R(cin,32);s.e2=R(32,64);s.e3=R(64,128);s.b=R(128,256);s.ms=nn.ModuleList([nn.Conv2d(256,256,3,padding=d,dilation=d) for d in (1,2,4)]);s.mix=nn.Conv2d(768,256,1);s.up3=nn.ConvTranspose2d(256,128,2,2);s.a3=A(128,128);s.d3=R(256,128);s.up2=nn.ConvTranspose2d(128,64,2,2);s.a2=A(64,64);s.d2=R(128,64);s.up1=nn.ConvTranspose2d(64,32,2,2);s.a1=A(32,32);s.d1=R(64,32);s.head=nn.Conv2d(32,3,1)
