import torch.nn as nn
import torch.nn.functional as F
class Res(nn.Module):
 def init(self,ci,co):
 super().init(); self.f=nn.Sequential(nn.Conv2d(ci,co,3,1,1,bias=False),nn.GroupNorm(8,co),nn.SiLU(),nn.Conv2d(co,co,3,1,1,bias=False),nn.GroupNorm(8,co)); self.s=nn.Identity() if ci==co else nn.Conv2d(ci,co,1)
 def forward(self,x): return F.silu(self.f(x)+self.s(x))
class AG(nn.Module):
 def init(self,cs,cg,c):
 super().init(); self.x=nn.Conv2d(cs,c,1); self.g=nn.Conv2d(cg,c,1); self.p=nn.Conv2d(c,1,1)
 def forward(self,x,g): return x*torch.sigmoid(self.p(F.silu(self.x(x)+self.g(g))))
class Dec(nn.Module):
 def init(self,ci,cs,co):
 super().init(); self.up=nn.ConvTranspose2d(ci,co,2,2); self.a=AG(cs,co,max(8,co//2)); self.r=Res(co+cs,co)
 def forward(self,x,s):
 x=self.up(x); return self.r(torch.cat([x,self.a(s,x)],1))").

