import torch.nn as nn
import torch.nn.functional as F
class RB(nn.Module):
 def init(self,a,b):
 super().init(); g=min(8,b); self.f=nn.Sequential(nn.Conv2d(a,b,3,1,1,bias=False),nn.GroupNorm(g,b),nn.SiLU(),nn.Conv2d(b,b,3,1,1,bias=False),nn.GroupNorm(g,b)); self.p=nn.Identity() if a==b else nn.Conv2d(a,b,1)
 def forward(self,x): return F.silu(self.f(x)+self.p(x))
class Gate(nn.Module):
 def init(self,s,g,o):
 super().init(); self.s=nn.Conv2d(s,o,1); self.g=nn.Conv2d(g,o,1); self.q=nn.Conv2d(o,1,1)
 def forward(self,s,g): return storch.sigmoid(self.q(F.silu(self.s(s)+self.g(g))))
class RAMHUNet(nn.Module):
 def __init__(self,nin=1,c=32):
 super().__init__(); self.e1,self.e2,self.e3,self.e4=RB(nin,c),RB(c,2c),RB(2c,4c),RB(4c,8c); self.bn=RB(8c,16c); self.up4,self.up3,self.up2,self.up1=[nn.ConvTranspose2d(a,b,2,2) for a,b in [(16c,8c),(8c,4c),(4c,2c),(2c,c)]]; self.g4,self.g3,self.g2,self.g1=Gate(8c,8c,4c),Gate(4c,4c,2c),Gate(2c,2c,c),Gate(c,c,c//2); self.d4,self.d3,self.d2,self.d1=RB(16c,8c),RB(8c,4c),RB(4c,2c),RB(2c,c); self.head=nn.Conv2d(c,3,1); self.pool=nn.MaxPool2d(2)
 def forward(self,x):
 a=self.e1(x); b=self.e2(self.pool(a)); c=self.e3(self.pool(b)); d=self.e4(self.pool(c)); z=self.bn(self.pool(d)); z=self.d4(torch.cat([self.up4(z),self.g4(d,self.up4(z))],1)); z=self.d3(torch.cat([self.up3(z),self.g3(c,self.up3(z))],1)); z=self.d2(torch.cat([self.up2(z),self.g2(b,self.up2(z))],1)); u=self.up1(z); return self.head(self.d1(torch.cat([u,self.g1(a,u)],1)))
